37	{
38	  if (n < 1)
39	     return 0;
40	
41	  /* Input and output, update data on negative edge read on positive, bits. */
42	  send_byte(MC_DATA_IN | MC_DATA_OUT | MC_DATA_BITS | MC_DATA_LSB );
43	  send_byte(n - 1);
44	  send_byte(data);
45	
46	  return recv_byte();
47	}
