50	{
51	  if (n < 1)
52	     return;
53	
54	  /* Input and output, update data on negative edge read on positive. */
55	  send_byte(MC_DATA_IN | MC_DATA_OUT | MC_DATA_LSB | MC_DATA_OCN);
56	  send_byte(n - 1);
57	  send_byte((n - 1) >> 8);
58	
59	  int rc = ftdi_write_data(&ftdic, data, n);
60	  if (rc != n) {
61	     fprintf(stderr, "Write error (chunk, rc=%d, expected %d).\n", rc, n);
62	     exit(2);
63	  }
64	
65	  for (int i = 0; i < n; i++)
